// ─── Validate and normalize OpenClaw product submission ──────────
const input = $input.first().json;

// Validate required fields
if (!input.title || !input.price_dollars) {
  throw new Error('Missing required fields: title and price_dollars');
}

const priceCents = Math.round((input.price_dollars || 0) * 100);
const sku = input.sku || `OC-${Date.now().toString(36).toUpperCase()}`;
const channels = input.channels || [];

console.log(`[OpenClaw] Product submission: ${input.title} at $${input.price_dollars}`);
console.log(`[OpenClaw] SKU: ${sku}, Channels: ${channels.join(', ') || 'none'}`);

return [{
  json: {
    title: input.title,
    description: input.description || '',
    price_cents: priceCents,
    price_dollars: input.price_dollars,
    sku: sku,
    channels: channels,
    image_url: input.image_url || null,
    condition: input.condition || 'good',
    source: 'openclaw-photo-pipeline',
    metadata: {
      inventory_item_id: input.inventory_item_id || null,
      channels: channels,
      source: 'openclaw-photo-pipeline',
      condition: input.condition || 'good',
      openclaw_session: input.session_id || null,
    }
  }
}];

const token = $input.first().json.token;
const product = $('Validate & Normalize').first().json;

// Build Medusa product payload
const payload = {
  title: product.title,
  description: product.description,
  status: 'published',
  metadata: product.metadata,
  options: [{ title: 'Type', values: ['Default'] }],
  variants: [{
    title: 'Default',
    sku: product.sku,
    options: { Type: 'Default' },
    prices: [{ amount: product.price_cents, currency_code: 'usd' }],
    manage_inventory: false
  }]
};

// Add image if provided
if (product.image_url) {
  payload.images = [{ url: product.image_url }];
}

return [{ json: { token, payload } }];

const result = $input.first().json;
const product = result.product || {};
const originalData = $('Validate & Normalize').first().json;

console.log(`[OpenClaw] ✓ Product created: ${product.id} — ${product.title}`);

// Return success response to OpenClaw
return [{
  json: {
    success: true,
    product_id: product.id,
    title: product.title,
    handle: product.handle,
    sku: originalData.sku,
    price: originalData.price_dollars,
    channels: originalData.channels,
    medusa_url: `http://localhost:9500/app/products/${product.id}`,
    message: `Created: ${product.title} for $${originalData.price_dollars} (${product.id})`
  }
}];
